import sailpoint.object.TaskDefinition;
import sailpoint.object.TaskResult;
import sailpoint.api.TaskManager;
import java.util.HashMap;

if (taskName == null || taskName.length() == 0) {
  return "FAIL: taskName required";
}
TaskDefinition td = context.getObjectByName(TaskDefinition.class, taskName);
if (td == null) {
  return "FAIL: TaskDefinition not found: " + taskName;
}
TaskManager tm = new TaskManager(context);
TaskResult tr = tm.runSync(td, new HashMap());
String status = (tr.getCompletionStatus() == null) ? "null" : tr.getCompletionStatus().toString();
return "OK task=" + taskName + " status=" + status + " result=" + tr.getName();
